// CONFIG: every Config node in this workflow holds this same block.
// Fastest setup: find-and-replace the __PLACEHOLDERS__ in the JSON file once before importing.
const CONFIG = {
  zohoApiDomain: 'https://www.zohoapis.com.au', // Zoho AU data centre. US: .com | EU: .eu | IN: .in
  booksOrgId: '__BOOKS_ORG_ID__',           // Zoho Books > Settings > Organisation Profile > Organisation ID
  booksItemId: '__BOOKS_ITEM_ID__',         // Books item used on invoice lines, e.g. "Software licence"
  paymentGateway: 'stripe',                       // gateway connected in Books > Settings > Online Payments ('' = none)
  paymentTermsDays: 14,
  flowWebhookUrl: '__ZOHO_FLOW_WEBHOOK_URL__',    // Zoho Flow > Webhook trigger URL
  crmFnRouteLeadUrl: '__CRM_FN_ROUTE_LEAD_URL__', // CRM function n8n_route_lead > REST API > API Key URL
  openAiModel: 'openai/gpt-oss-120b',
  reminderCadenceDays: [1, 7, 14, 21, 30],        // days overdue that get a reminder; weekly after the last one
  escalateAfterDays: 21,                          // from this many days overdue, a CRM task is created too
  timezone: 'Australia/Sydney',
};
CONFIG.crmApi = `${CONFIG.zohoApiDomain}/crm/v8`;
CONFIG.booksApi = `${CONFIG.zohoApiDomain}/books/v3`;

// Stop early with a clear message if a value this automation needs is still a placeholder.
const NEEDS = ['crmFnRouteLeadUrl', 'flowWebhookUrl'];
const unset = NEEDS.filter((k) => /^__.+__$/.test(String(CONFIG[k])));
if (unset.length) throw new Error('Fill in the Config node first: ' + unset.join(', '));

return $input.all().map((item) => ({ json: { ...item.json, config: CONFIG } }));

// Validates the form again on the server (never trust the browser), with a honeypot and length caps.
const body = $('Website Lead (PHP form)').first().json.body || {};
const clean = (v, max = 255) => String(v ?? '').replace(/[\u0000-\u001F\u007F]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const cleanText = (v, max) => String(v ?? '').replace(/[\u0000-\u0009\u000B-\u001F\u007F]+/g, ' ').trim().slice(0, max);

// Honeypot: a hidden field real visitors never fill. Bots get a normal "thanks" and nothing is saved.
if (clean(body.company_website)) {
  return [{ json: { valid: false, spam: true, errors: [] } }];
}

const errors = [];
const email = clean(body.email, 254).toLowerCase();
if (!/^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/.test(email)) errors.push('Please enter a valid work email.');
const fullName = clean(body.name, 120);
if (fullName.length < 2) errors.push('Please enter your name.');
const message = cleanText(body.message, 2000);
if (message.length < 10) errors.push('Please tell us a little more about what you need.');

// Zoho CRM requires Last_Name on a lead.
const parts = fullName.split(' ').filter(Boolean);
const lastName = parts.length > 1 ? parts[parts.length - 1] : fullName;
const firstName = parts.length > 1 ? parts.slice(0, -1).join(' ') : '';

const domain = email.split('@')[1] || '';
const FREEMAIL = ['gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.com.au', 'outlook.com', 'hotmail.com', 'live.com',
  'icloud.com', 'bigpond.com', 'bigpond.net.au', 'optusnet.com.au', 'proton.me', 'protonmail.com', 'aol.com'];
const consent = ['on', 'true', '1', 'yes'].includes(String(body.marketing_consent ?? '').toLowerCase());

return [{ json: {
  valid: errors.length === 0,
  spam: false,
  errors,
  lead: {
    first_name: firstName,
    last_name: lastName,
    full_name: fullName,
    email,
    email_domain: domain,
    is_freemail: FREEMAIL.includes(domain),
    company: clean(body.company, 120) || 'Not provided', // Company is mandatory on Zoho leads
    phone: clean(body.phone, 30).replace(/[^\d+()\-\s]/g, ''),
    interest: clean(body.interest, 60),
    message,
    marketing_consent: consent,
    page_url: clean(body.page_url, 300),
    utm_source: clean(body.utm_source, 100),
    utm_medium: clean(body.utm_medium, 100),
    utm_campaign: clean(body.utm_campaign, 100),
    submitted_at: new Date().toISOString(),
  },
} }];

