// The Books Deluge function sends only the payment ID; the payment is re-read from Books.
const body = $('Books Payment Received (Deluge)').first().json.body || {};
const id = String(body.payment_id ?? '').trim();
if (!/^\d{6,25}$/.test(id)) {
  throw new Error(`Ignored payment event: payment_id "${id.slice(0, 40)}" is not a Zoho Books id.`);
}
