// One payment can settle several invoices: one item per invoice it was applied to.
const p = $input.first().json.payment || {};
return (p.invoices || [])
  .filter((i) => Number(i.amount_applied) > 0)
  .map((i) => ({ json: {
    payment_id: String(p.payment_id),
    payment_date: String(p.date || ''),
    payment_mode: String(p.payment_mode || ''),
    customer_name: String(p.customer_name || ''),
    invoice_id: String(i.invoice_id),
    invoice_number: String(i.invoice_number || ''),
    amount_applied: Number(i.amount_applied),
  } }));

// Links each paid invoice back to its CRM deal through the CRM-DEAL-<id> reference set at invoicing time.
const applied = $('Split Applied Invoices').all();
const res = $input.all();
const out = [];
applied.forEach((a, i) => {
  const inv = res[i]?.json?.invoice || {};
  const m = String(inv.reference_number || '').trim().match(/^CRM-DEAL-(\d+)$/);
  if (!m) return; // invoice wasn't created from a CRM deal: nothing to sync
  const balance = Number(inv.balance) || 0;
  out.push({ json: {
    ...a.json,
    deal_id: m[1],
    balance,
    invoice_total: Number(inv.total) || 0,
    currency_code: String(inv.currency_code || ''),
    status: balance <= 0 ? 'Paid' : 'Partially Paid',
  } });
});
return out;

